<div class="page-actions"><div><p class="mb-0">Customer request dengan SLA deadline dan quick conversion ke Survey, Quotation, atau Job.</p></div><button class="btn btn-primary" data-bs-toggle="modal" data-bs-target="#requestModal">New Request</button></div>
<div class="card-panel"><div class="table-responsive"><table class="table align-middle datatable"><thead><tr><th>Request</th><th>Customer</th><th>Problem</th><th>Priority</th><th>SLA</th><th>Status</th><th>Convert</th></tr></thead><tbody><?php foreach($requests as $r): $breach=$r['resolution_deadline']&&strtotime($r['resolution_deadline'])<time()&&!in_array($r['status'],['Completed','Closed','Cancelled'],true); ?><tr><td><strong><?= e($r['request_number']) ?></strong><small class="d-block text-secondary"><?= e($r['requested_date']??'') ?></small></td><td><?= e($r['customer_name']) ?><small class="d-block text-secondary"><?= e($r['site_name']??$r['asset_code']??'') ?></small></td><td><?= e(mb_strimwidth($r['problem_description'],0,65,'…')) ?></td><td><?= e($r['priority']) ?></td><td><span class="status-badge <?= $breach?'danger':'' ?>"><?= $breach?'BREACHED':e($r['resolution_deadline']??'No SLA') ?></span></td><td><span class="status-badge"><?= e($r['status']) ?></span></td><td><div class="btn-group"><button class="btn btn-sm btn-light ajax-action" data-url="<?= url('/service-requests/'.$r['id'].'/convert/survey') ?>">Survey</button><button class="btn btn-sm btn-light ajax-action" data-url="<?= url('/service-requests/'.$r['id'].'/convert/quotation') ?>">Quote</button><button class="btn btn-sm btn-light ajax-action" data-url="<?= url('/service-requests/'.$r['id'].'/convert/job') ?>">Job</button><button class="btn btn-sm btn-light collab-btn" data-entity="service_request" data-id="<?= $r['id'] ?>"><i class="bi bi-paperclip"></i></button></div></td></tr><?php endforeach; ?></tbody></table></div></div>
<div class="modal fade" id="requestModal"><div class="modal-dialog modal-lg"><form class="modal-content ajax-form" method="post" action="<?= url('/service-requests') ?>"><?= csrf_field() ?><div class="modal-header"><h5>New Service Request</h5><button class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body row g-3"><div class="col-md-6"><label class="form-label">Customer</label><select class="form-select" name="customer_id" id="requestCustomer" required><option value="">Select</option><?php foreach($customers as $c): ?><option value="<?= $c['id'] ?>"><?= e($c['name']) ?></option><?php endforeach; ?></select></div><div class="col-md-3"><label class="form-label">Site</label><select class="form-select relational-select" name="site_id" data-parent="#requestCustomer"><option value="">Optional</option><?php foreach($sites as $s): ?><option value="<?= $s['id'] ?>" data-parent-value="<?= $s['customer_id'] ?>"><?= e($s['site_name']) ?></option><?php endforeach; ?></select></div><div class="col-md-3"><label class="form-label">Asset</label><select class="form-select relational-select" name="asset_id" data-parent="#requestCustomer"><option value="">Optional</option><?php foreach($assets as $a): ?><option value="<?= $a['id'] ?>" data-parent-value="<?= $a['customer_id'] ?>"><?= e($a['asset_code'].' · '.$a['category']) ?></option><?php endforeach; ?></select></div><div class="col-md-6"><label class="form-label">Category</label><input class="form-control" name="service_category" placeholder="CCTV, Network, AC..."></div><div class="col-md-3"><label class="form-label">Priority</label><select class="form-select" name="priority"><option>Low</option><option selected>Normal</option><option>High</option><option>Urgent</option><option>Emergency</option></select></div><div class="col-md-3"><label class="form-label">Requested Date</label><input type="date" class="form-control" name="requested_date"></div><div class="col-12"><label class="form-label">Problem Description</label><textarea class="form-control" rows="4" name="problem_description" required></textarea></div><div class="col-md-6"><label class="form-label">Contact Person</label><input class="form-control" name="contact_person"></div></div><div class="modal-footer"><button class="btn btn-light" type="button" data-bs-dismiss="modal">Cancel</button><button class="btn btn-primary">Create Request</button></div></form></div></div>
